namespace Pickleball.Cutscene.Editor.Actors
{
    /// <summary>
    /// Every asset path the characters workstream reads or writes, in one place so the menus,
    /// the tests and the docs agree. Paths under Art/Characters and Animation/Birdy|Chibi are
    /// read-only sources; everything else is generated by <see cref="CutsceneActorSetup"/>.
    /// </summary>
    public static class CutsceneActorPaths
    {
        // ---- read-only sources -------------------------------------------------------------
        /// <summary>MC's model (Tripo chibi, Humanoid, 52 bones incl. fingers).</summary>
        public const string ChibiModel = "Assets/_Project/Art/Characters/Chibi/chibi_unity.fbx";

        /// <summary>
        /// MC's base-colour texture as the live material uses it (Art/Chibi/Chibi.mat, which the
        /// FBX remaps to). Byte-identical to the copy beside the FBX, which the eye variant was
        /// painted from.
        /// </summary>
        public const string ChibiBaseColor = "Assets/_Project/Art/Chibi/chibi+character+3d+model_basecolor.jpg";

        /// <summary>Birdy's model (Tripo, Humanoid, wings = arms; Rotor bone added on import).</summary>
        public const string BirdyModel = "Assets/_Project/Art/Characters/Birdy/Birdy.fbx";

        /// <summary>Birdy's material (shared, never edited).</summary>
        public const string BirdyMaterial = "Assets/_Project/Art/Characters/Birdy/Birdy.mat";

        /// <summary>Birdy's base-colour texture.</summary>
        public const string BirdyBaseColor = "Assets/_Project/Art/Characters/Birdy/Birdy_BaseColor.jpg";

        /// <summary>MC's existing Mixamo clips (reused by reference).</summary>
        public const string ChibiClipDir = "Assets/_Project/Animation/Chibi";

        /// <summary>Birdy's existing Mixamo clips (reused by reference, never re-imported).</summary>
        public const string BirdyClipDir = "Assets/_Project/Animation/Birdy";

        // ---- owned by this workstream --------------------------------------------------------
        /// <summary>Art root (propeller mesh, eye variants).</summary>
        public const string ArtDir = "Assets/_Project/Art/Cutscene/Characters";

        /// <summary>The propeller, extracted from Birdy.fbx by Tools/Blender/cutscene_extract_propeller.py.</summary>
        public const string PropellerModel = ArtDir + "/Birdy/BirdyPropeller.fbx";

        /// <summary>MC's closed-eyes base map (Tools/Blender/cutscene_paint_eyes.py chibi_closed).</summary>
        public const string ChibiEyesClosed = ArtDir + "/Chibi/Chibi_EyesClosed.jpg";

        /// <summary>Birdy's dropped-lids base map (Tools/Blender/cutscene_paint_eyes.py birdy_drop).</summary>
        public const string BirdyEyesDrop = ArtDir + "/Birdy/Birdy_EyesDrop.jpg";

        /// <summary>Clip root.</summary>
        public const string AnimDir = "Assets/_Project/Animation/Cutscene";

        /// <summary>MC's generated and copied clips.</summary>
        public const string McClipDir = AnimDir + "/MC";

        /// <summary>Birdy's generated and copied clips.</summary>
        public const string BirdyCutsceneClipDir = AnimDir + "/Birdy";

        /// <summary>Actor prefab folder.</summary>
        public const string PrefabDir = "Assets/_Project/Prefabs/Cutscene/Actors";

        /// <summary>The standalone MC slot.</summary>
        public const string McActorPrefab = PrefabDir + "/MC_Actor.prefab";

        /// <summary>Birdy's slot.</summary>
        public const string BirdyActorPrefab = PrefabDir + "/Birdy_Actor.prefab";

        /// <summary>The loose propeller.</summary>
        public const string PropellerPrefab = PrefabDir + "/Propeller.prefab";

        /// <summary>Data folder (libraries and configs).</summary>
        public const string DataDir = "Assets/_Project/ScriptableObjects/Cutscene/Actors";

        /// <summary>MC's verb → clip map.</summary>
        public const string McLibrary = DataDir + "/MC_ActionLibrary.asset";

        /// <summary>Birdy's verb → clip map.</summary>
        public const string BirdyLibrary = DataDir + "/Birdy_ActionLibrary.asset";

        /// <summary>Spin tunables (seeded once).</summary>
        public const string PropellerConfig = DataDir + "/PropellerConfig.asset";

        /// <summary>MC's mouth flap tunables (seeded once).</summary>
        public const string McMouthFlap = DataDir + "/MC_MouthFlap.asset";

        /// <summary>Birdy's mouth flap tunables (seeded once).</summary>
        public const string BirdyMouthFlap = DataDir + "/Birdy_MouthFlap.asset";

        /// <summary>The approved shot list (verbs are read from its §6 by the coverage test).</summary>
        public const string ShotList = "Docs/Story/OpeningCutscenes_ShotList.md";
    }
}
